from datetime import datetime, timezone
from math import isfinite, log2, ldexp

PROVIDERS = {"DeepSeek", "Mistral", "Synthetic"}
CLASSES = {"NETWORK", "AUTH", "INVALID", "LIMIT", "SAFETY", "CONTEXT", "PROVIDER", "APP", "DOWNSTREAM"}
TRANSIENT = {"NETWORK", "LIMIT", "PROVIDER"}
STATES = {"none", "complete", "unknown"}

STATUS_RULES = {
    "DeepSeek": {
        400: ("INVALID", {400}), 401: ("AUTH", {401}), 402: ("LIMIT", {402}),
        422: ("INVALID", {422}), 429: ("LIMIT", {429}), 500: ("PROVIDER", {500}),
        503: ("PROVIDER", {503}),
    },
    "Mistral": {
        400: ("INVALID", {400}), 401: ("AUTH", {401}), 403: ("AUTH", {403}),
        404: ("INVALID", {404}), 422: ("INVALID", {422}), 429: ("LIMIT", {429}),
        500: ("PROVIDER", {500}), 502: ("PROVIDER", {502}),
        503: ("PROVIDER", {503}), 504: ("PROVIDER", {504}),
    },
    "Synthetic": {
        200: ({"APP", "SAFETY"}, {"PARSE_ERROR", "SAFETY_STOP"}),
        400: ("CONTEXT", {"CONTEXT_LIMIT"}), 401: ("AUTH", {401}),
        402: ("LIMIT", {402}), 422: ("INVALID", {422}), 429: ("LIMIT", {429}),
        500: ("PROVIDER", {500}), 503: ("PROVIDER", {503}),
    },
}

TEXT_FIELDS = (
    "service", "operation", "route", "endpoint_version", "model", "region",
    "environment", "timestamp_utc", "correlation_id", "operation_id",
    "provider_request_id", "redacted_sensitive_review", "reproduction",
    "owner_cadence", "stop_criteria", "recovery_escalation", "verification",
)
NUMERIC_FIELDS = (
    "deadline_seconds", "elapsed_seconds", "attempt_timeout_seconds",
    "backoff_base_seconds", "max_delay_seconds", "minimum_delay_seconds",
    "jitter_low_seconds", "jitter_high_seconds", "deterministic_jitter",
    "next_attempt_cost", "remaining_cost_budget",
)
REQUIRED = (
    "provider", "transport_observed", "http_status", "error_code", "failure_class",
    "layer_attempts", "attempts_performed", "total_attempt_budget", "safety_stop",
    "side_effect_state", "redacted_effective_configuration",
) + TEXT_FIELDS + NUMERIC_FIELDS
CONFIG_KEYS = {
    "shared_attempt_budget", "sdk_retries_counted", "proxy_retries_counted",
    "application_retries_counted", "exponential_indexing", "max_delay_scope",
    "jitter_source",
}


def nonnegative(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(name)
    try:
        finite = isfinite(value)
    except (OverflowError, ValueError, TypeError) as exc:
        raise ValueError(name) from exc
    if not finite or value < 0:
        raise ValueError(name)
    try:
        return float(value)
    except (OverflowError, ValueError, TypeError) as exc:
        raise ValueError(name) from exc


def positive(value, name):
    result = nonnegative(value, name)
    if result <= 0:
        raise ValueError(name)
    return result


def nonnegative_int(value, name):
    if isinstance(value, bool) or not isinstance(value, int) or value < 0:
        raise ValueError(name)
    return value


def valid_error_code(value):
    if isinstance(value, bool):
        return False
    if isinstance(value, int):
        return value >= 0
    return isinstance(value, str) and bool(value.strip())


def validate_config(config, total_budget):
    if not isinstance(config, dict) or set(config) != CONFIG_KEYS:
        raise ValueError("effective_configuration")
    shared = config["shared_attempt_budget"]
    if (isinstance(shared, bool) or not isinstance(shared, int)
            or shared < 0 or shared != total_budget):
        raise ValueError("shared_attempt_budget")
    for key in ("sdk_retries_counted", "proxy_retries_counted", "application_retries_counted"):
        if config[key] is not True:
            raise ValueError(key)
    if config["exponential_indexing"] != "first_performed_attempt_is_exponent_zero":
        raise ValueError("exponential_indexing")
    if config["max_delay_scope"] != "exponential_component_only":
        raise ValueError("max_delay_scope")
    if config["jitter_source"] != "deterministic_injected_fixture":
        raise ValueError("jitter_source")


def validate(record):
    for key in REQUIRED:
        if key not in record:
            raise ValueError("missing:" + key)
    if record["provider"] not in PROVIDERS:
        raise ValueError("provider")
    for key in TEXT_FIELDS:
        if not isinstance(record[key], str) or not record[key].strip():
            raise ValueError(key)
    if not isinstance(record["transport_observed"], bool) or not isinstance(record["safety_stop"], bool):
        raise ValueError("flag")
    if record["failure_class"] not in CLASSES or record["side_effect_state"] not in STATES:
        raise ValueError("class_or_state")
    if not valid_error_code(record["error_code"]):
        raise ValueError("error_code")
    status = record["http_status"]
    if status is not None and (isinstance(status, bool) or not isinstance(status, int) or not 100 <= status <= 599):
        raise ValueError("http_status")
    if record["transport_observed"] != (status is not None):
        raise ValueError("transport_status")
    for key in ("attempts_performed", "total_attempt_budget"):
        nonnegative_int(record[key], key)
    layers = record["layer_attempts"]
    if not isinstance(layers, dict) or set(layers) != {"sdk", "proxy", "application"}:
        raise ValueError("layer_attempts")
    for key in layers:
        nonnegative_int(layers[key], "layer_" + key)
    if sum(layers.values()) != record["attempts_performed"]:
        raise ValueError("layer_attempt_sum")
    if record["attempts_performed"] > record["total_attempt_budget"]:
        raise ValueError("attempts_over_budget")
    for key in NUMERIC_FIELDS:
        nonnegative(record[key], key)
    positive(record["attempt_timeout_seconds"], "attempt_timeout_seconds")
    if record["elapsed_seconds"] > record["deadline_seconds"]:
        raise ValueError("elapsed_over_deadline")
    if record["jitter_low_seconds"] > record["jitter_high_seconds"]:
        raise ValueError("jitter_bounds")
    if not record["jitter_low_seconds"] <= record["deterministic_jitter"] <= record["jitter_high_seconds"]:
        raise ValueError("jitter_value")
    validate_config(record["redacted_effective_configuration"], record["total_attempt_budget"])
    if record["safety_stop"] != (record["failure_class"] == "SAFETY"):
        raise ValueError("safety_class")
    if status is None:
        if record["failure_class"] != "NETWORK" or record["error_code"] != "TRANSPORT_UNKNOWN":
            raise ValueError("missing_transport_mapping")
        return
    if record["failure_class"] == "NETWORK":
        raise ValueError("network_with_response")
    rule = STATUS_RULES[record["provider"]].get(status)
    if rule is None:
        raise ValueError("unsupported_status")
    expected_class, expected_codes = rule
    if (record["failure_class"] not in expected_class if isinstance(expected_class, set)
            else record["failure_class"] != expected_class):
        raise ValueError("status_class")
    if record["error_code"] not in expected_codes:
        raise ValueError("status_error_code")
    if status == 200:
        expected = "SAFETY_STOP" if record["failure_class"] == "SAFETY" else "PARSE_ERROR"
        if record["error_code"] != expected:
            raise ValueError("http200_error_code")


def bounded_exponential(base, cap, attempts_performed):
    base = float(base)
    cap = float(cap)
    if base == 0.0 or cap == 0.0:
        return 0.0
    if base >= cap:
        return cap
    exponent = max(attempts_performed - 1, 0)
    threshold = log2(cap) - log2(base)
    if exponent >= threshold:
        return cap
    try:
        return min(cap, ldexp(base, exponent))
    except (OverflowError, ValueError) as exc:
        raise ValueError("exponential") from exc


def decide(record):
    validate(record)
    trace = {"remaining": record["deadline_seconds"] - record["elapsed_seconds"], "proposed_delay": 0.0}
    if record["side_effect_state"] == "complete":
        return ("STOP", "SIDE_EFFECT_COMPLETE", 0, 0.0, trace)
    if record["side_effect_state"] == "unknown":
        return ("STOP", "UNKNOWN_SIDE_EFFECT", 0, 0.0, trace)
    if record["failure_class"] == "SAFETY":
        return ("STOP", "SAFETY_CONTROL", 0, 0.0, trace)
    if record["failure_class"] not in TRANSIENT:
        return ("STOP", "NON_TRANSIENT_" + record["failure_class"], 0, 0.0, trace)
    if record["provider"] == "DeepSeek" and record["http_status"] == 402:
        return ("STOP", "INSUFFICIENT_BALANCE", 0, 0.0, trace)
    if record["attempts_performed"] >= record["total_attempt_budget"]:
        return ("STOP", "ATTEMPT_BUDGET_EXHAUSTED", 0, 0.0, trace)
    if record["next_attempt_cost"] > record["remaining_cost_budget"]:
        return ("STOP", "COST_BUDGET", 0, 0.0, trace)
    exponential = bounded_exponential(record["backoff_base_seconds"], record["max_delay_seconds"], record["attempts_performed"])
    delay = max(record["minimum_delay_seconds"], exponential) + record["deterministic_jitter"]
    trace["proposed_delay"] = delay
    if trace["remaining"] <= 0 or delay + record["attempt_timeout_seconds"] > trace["remaining"]:
        return ("STOP", "DEADLINE", 0, 0.0, trace)
    return ("RETRY", "TRANSIENT_WITHIN_BUDGET", 1, delay, trace)


def layer_counts(attempts):
    sdk = min(attempts, 1)
    proxy = min(max(attempts - 1, 0), 1)
    return {"sdk": sdk, "proxy": proxy, "application": attempts - sdk - proxy}


def rec(name, **changes):
    record = dict(
        provider="Synthetic", service="ai-gateway", operation="generate_answer", route="/v1/answer",
        endpoint_version="normalized-v1", model="redacted-model", region="test-region-1",
        environment="offline-lab", timestamp_utc="2026-09-20T10:15:00Z",
        correlation_id="corr-" + name, operation_id="op-" + name, provider_request_id="req-" + name,
        transport_observed=True, http_status=503, error_code=503, failure_class="PROVIDER",
        attempts_performed=1, total_attempt_budget=3, deadline_seconds=20.0, elapsed_seconds=1.0,
        attempt_timeout_seconds=1.0, backoff_base_seconds=0.0, max_delay_seconds=30.0,
        minimum_delay_seconds=0.0, jitter_low_seconds=0.0, jitter_high_seconds=0.0,
        deterministic_jitter=0.0, next_attempt_cost=0.4, remaining_cost_budget=1.0,
        safety_stop=False, side_effect_state="none",
        redacted_effective_configuration={
            "shared_attempt_budget": 3, "sdk_retries_counted": True,
            "proxy_retries_counted": True, "application_retries_counted": True,
            "exponential_indexing": "first_performed_attempt_is_exponent_zero",
            "max_delay_scope": "exponential_component_only",
            "jitter_source": "deterministic_injected_fixture",
        },
        redacted_sensitive_review="secrets, prompts, user content, authorization, and unrestricted output removed",
        reproduction="offline normalized fixture only", owner_cadence="offline fixture",
        stop_criteria="side effect, safety, class, attempt, cost, and deadline gates",
        recovery_escalation="reconcile uncertain operations; otherwise escalate with redacted IDs",
        verification="same route and model, parsing, named-window metrics, and downstream postcondition",
    )
    record.update(changes)
    if "layer_attempts" not in changes:
        record["layer_attempts"] = layer_counts(record["attempts_performed"])
    record["redacted_effective_configuration"] = dict(record["redacted_effective_configuration"])
    record["redacted_effective_configuration"]["shared_attempt_budget"] = record["total_attempt_budget"]
    return record


