        "downstream_postcondition_confirmed": True,
        "application_observation": "successful parsing and postcondition in authored offline fixture",
    }


def parse_utc_window(value):
    if not isinstance(value, str) or "/" not in value:
        raise ValueError("observation_window")
    start_text, end_text = value.split("/", 1)
    if not start_text.endswith("Z") or not end_text.endswith("Z"):
        raise ValueError("observation_window_utc")
    try:
        start = datetime.fromisoformat(start_text[:-1] + "+00:00")
        end = datetime.fromisoformat(end_text[:-1] + "+00:00")
    except (TypeError, ValueError, OverflowError) as exc:
        raise ValueError("observation_window") from exc
    if start.tzinfo is None or end.tzinfo is None or start.utcoffset() != timezone.utc.utcoffset(start) or end.utcoffset() != timezone.utc.utcoffset(end):
        raise ValueError("observation_window_utc")
    if end <= start:
        raise ValueError("observation_window_order")
    return start, end


def verify_recovery(evidence):
    required = {"provider", "service", "route", "model", "effective_configuration", "environment", "operation_id", "correlation_id", "provider_request_id", "representative_request_same_boundary", "application_parsing_success", "observation_window", "error_count", "request_count", "max_error_rate", "latency_samples_seconds", "max_latency_seconds", "quality_pass_count", "quality_sample_count", "minimum_quality_rate", "downstream_postcondition_confirmed", "application_observation"}
    if not isinstance(evidence, dict) or not required.issubset(evidence):
        return ("UNKNOWN", None)
    try:
        parse_utc_window(evidence["observation_window"])
        for key in ("provider", "service", "route", "model", "effective_configuration", "environment", "operation_id", "correlation_id", "provider_request_id", "application_observation"):
            if not isinstance(evidence[key], str) or not evidence[key].strip():
                return ("UNKNOWN", None)
        for key in ("representative_request_same_boundary", "application_parsing_success", "downstream_postcondition_confirmed"):
            if not isinstance(evidence[key], bool):
                return ("UNKNOWN", None)
        errors = nonnegative_int(evidence["error_count"], "error_count")
        requests = nonnegative_int(evidence["request_count"], "request_count")
        quality_pass = nonnegative_int(evidence["quality_pass_count"], "quality_pass_count")
        quality_total = nonnegative_int(evidence["quality_sample_count"], "quality_sample_count")
        if requests == 0 or quality_total == 0 or errors > requests or quality_pass > quality_total:
            return ("UNKNOWN", None)
        max_error = nonnegative(evidence["max_error_rate"], "max_error_rate")
        max_latency = positive(evidence["max_latency_seconds"], "max_latency_seconds")
        min_quality = nonnegative(evidence["minimum_quality_rate"], "minimum_quality_rate")
        if max_error > 1 or min_quality > 1:
            return ("UNKNOWN", None)
        samples = evidence["latency_samples_seconds"]
        if not isinstance(samples, list) or not samples:
            return ("UNKNOWN", None)
        latencies = [nonnegative(value, "latency") for value in samples]
    except (ValueError, OverflowError, TypeError):
        return ("UNKNOWN", None)
    metrics = {"error_rate": errors / requests, "latency_max": max(latencies), "quality_rate": quality_pass / quality_total}
    passed = (evidence["representative_request_same_boundary"] and evidence["application_parsing_success"] and evidence["downstream_postcondition_confirmed"] and metrics["error_rate"] <= max_error and metrics["latency_max"] <= max_latency and metrics["quality_rate"] >= min_quality)
    return ("RECOVERED" if passed else "NOT_RECOVERED", metrics)


def assigned_task_fixture():
    return rec("assigned", provider="DeepSeek", http_status=500, error_code=500, failure_class="PROVIDER", attempts_performed=2, total_attempt_budget=3, elapsed_seconds=9.5, deadline_seconds=10.0, attempt_timeout_seconds=0.1, backoff_base_seconds=0.5, max_delay_seconds=30.0, minimum_delay_seconds=1.0, jitter_low_seconds=0.0, jitter_high_seconds=0.2, deterministic_jitter=0.1, next_attempt_cost=0.4, remaining_cost_budget=1.0)


def expect_error(record):
    try:
        decide(record)
    except ValueError:
        return
    raise AssertionError("invalid record accepted")


def run_tests():
    assert decide(rec("auth", provider="DeepSeek", http_status=401, error_code=401, failure_class="AUTH"))[1] == "NON_TRANSIENT_AUTH"
    assert decide(rec("balance", provider="DeepSeek", http_status=402, error_code=402, failure_class="LIMIT"))[1] == "INSUFFICIENT_BALANCE"
    assert decide(rec("complete", side_effect_state="complete"))[1] == "SIDE_EFFECT_COMPLETE"
    assert decide(rec("unknown", transport_observed=False, http_status=None, error_code="TRANSPORT_UNKNOWN", failure_class="NETWORK", provider_request_id="UNKNOWN", side_effect_state="unknown"))[1] == "UNKNOWN_SIDE_EFFECT"
    expect_error(rec("http200provider", http_status=200, error_code="PARSE_ERROR", failure_class="PROVIDER"))
    expect_error(rec("deepseek401provider", provider="DeepSeek", http_status=401, error_code=401, failure_class="PROVIDER"))
    expect_error(rec("mismatch", provider="DeepSeek", http_status=503, error_code=401, failure_class="PROVIDER"))
    expect_error(rec("listcode", error_code=[]))
    expect_error(rec("bool", attempt_timeout_seconds=True))
    expect_error(rec("nan", max_delay_seconds=float("nan")))
    expect_error(rec("inf", max_delay_seconds=float("inf")))
    expect_error(rec("negative", remaining_cost_budget=-1))
    expect_error(rec("missingid", correlation_id=""))
    expect_error(rec("transport", transport_observed=False, http_status=503))
    expect_error(rec("over", attempts_performed=4, total_attempt_budget=3))
    expect_error(rec("elapsed", elapsed_seconds=21.0, deadline_seconds=20.0))
    expect_error(rec("jitter", jitter_low_seconds=0.0, jitter_high_seconds=0.1, deterministic_jitter=0.2))
    bad = rec("badconfig"); bad["redacted_effective_configuration"]["shared_attempt_budget"] = 0; expect_error(bad)
    bad = rec("badflag"); bad["redacted_effective_configuration"]["sdk_retries_counted"] = False; expect_error(bad)
    bad = rec("badindex"); bad["redacted_effective_configuration"]["exponential_indexing"] = "last"; expect_error(bad)
    bad = rec("huge"); bad["deadline_seconds"] = 10 ** 400; expect_error(bad)
    assert decide(rec("cost", next_attempt_cost=1.1, remaining_cost_budget=1.0))[1] == "COST_BUDGET"
    assert decide(rec("zero", deadline_seconds=1.0, elapsed_seconds=1.0))[1] == "DEADLINE"
    assert decide(rec("tight", deadline_seconds=2.0, elapsed_seconds=1.0, attempt_timeout_seconds=1.1))[1] == "DEADLINE"
    assert decide(rec("hugeattempt", attempts_performed=10000, total_attempt_budget=10001, backoff_base_seconds=0.0))[0] == "RETRY"
    assert verify_recovery(recovery_fixture())[0] == "RECOVERED"
    incomplete = recovery_fixture(); del incomplete["latency_samples_seconds"]; assert verify_recovery(incomplete)[0] == "UNKNOWN"
    missing = recovery_fixture(); del missing["observation_window"]; assert verify_recovery(missing)[0] == "UNKNOWN"
    reversed_window = recovery_fixture(); reversed_window["observation_window"] = "2026-09-20T10:25:00Z/2026-09-20T10:20:00Z"; assert verify_recovery(reversed_window)[0] == "UNKNOWN"
    equal_window = recovery_fixture(); equal_window["observation_window"] = "2026-09-20T10:20:00Z/2026-09-20T10:20:00Z"; assert verify_recovery(equal_window)[0] == "UNKNOWN"
    nan_evidence = recovery_fixture(); nan_evidence["max_latency_seconds"] = float("nan"); assert verify_recovery(nan_evidence)[0] == "UNKNOWN"
    inf_evidence = recovery_fixture(); inf_evidence["error_count"] = 10 ** 400; assert verify_recovery(inf_evidence)[0] == "UNKNOWN"
    print("tests: 32 passed")


def main():
    fixtures = [
        rec("auth", provider="DeepSeek", http_status=401, error_code=401, failure_class="AUTH"),
        rec("invalid", provider="DeepSeek", http_status=422, error_code=422, failure_class="INVALID"),
        rec("balance", provider="DeepSeek", http_status=402, error_code=402, failure_class="LIMIT"),
        rec("throttle", provider="Mistral", http_status=429, error_code=429, failure_class="LIMIT", backoff_base_seconds=2.0, minimum_delay_seconds=2.0, jitter_low_seconds=0.25, jitter_high_seconds=0.75, deterministic_jitter=0.50),
        rec("server", provider="DeepSeek", http_status=503, error_code=503, failure_class="PROVIDER", attempts_performed=2, deadline_seconds=10.0, elapsed_seconds=3.0, backoff_base_seconds=0.5, max_delay_seconds=1.0, minimum_delay_seconds=1.0, jitter_high_seconds=0.5, deterministic_jitter=0.25),
        rec("exhausted", provider="Mistral", http_status=429, error_code=429, failure_class="LIMIT", attempts_performed=3),
        rec("unknown", transport_observed=False, http_status=None, error_code="TRANSPORT_UNKNOWN", failure_class="NETWORK", provider_request_id="UNKNOWN", side_effect_state="unknown"),
        rec("safety", http_status=200, error_code="SAFETY_STOP", failure_class="SAFETY", safety_stop=True),
        rec("parse", http_status=200, error_code="PARSE_ERROR", failure_class="APP"),
    ]
    for index, fixture in enumerate(fixtures, 1):
        result = decide(fixture)
        print("case%d: %s reason=%s reserved=%d delay=%.2f" % (index, result[0], result[1], result[2], result[3]))
    run_tests()
    recovery_status, metrics = verify_recovery(recovery_fixture())
    print("recovery: %s error_rate=%.3f latency_max=%.2f quality_rate=%.3f" % (recovery_status, metrics["error_rate"], metrics["latency_max"], metrics["quality_rate"]))
    result = decide(assigned_task_fixture())
    print("independent_probe: %s reason=%s reserved=%d delay=%.2f" % (result[0], result[1], result[2], result[3]))


if __name__ == "__main__":
    main()
